// ================================================================== хранение ==

let db = { users: {}, chats: {}, sessions: {} };
const dirty = { users: new Set(), chats: new Set(), sessions: new Set() };
const HKEY = { users: 'msgr:users', chats: 'msgr:chats', sessions: 'msgr:sessions' };

let flushTimer = null;
let flushing = false;

function touch(kind, key) {
  dirty[kind].add(key);
  scheduleFlush();
}

function scheduleFlush(delay) {
  if (flushTimer) return;
  flushTimer = setTimeout(() => {
    flushTimer = null;
    flush().catch((e) => console.error('Ошибка сохранения:', e.message));
  }, delay || (USE_REDIS ? 800 : 300));
}

async function redisPipeline(cmds) {
  const res = await fetch(REDIS_URL + '/pipeline', {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + REDIS_TOKEN, 'Content-Type': 'application/json' },
    body: JSON.stringify(cmds),
  });
  if (!res.ok) throw new Error(`Redis HTTP ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const arr = await res.json();
  for (const r of arr) if (r && r.error) throw new Error('Redis: ' + r.error);
  return arr.map((r) => r.result);
}

function pairsToObject(flat) {
  const out = {};
  if (!Array.isArray(flat)) return out;
  for (let i = 0; i + 1 < flat.length; i += 2) {
    try {
      out[flat[i]] = JSON.parse(flat[i + 1]);
    } catch {
      /* битую запись пропускаем */
    }
  }
  return out;
}

async function loadDb() {
  if (USE_REDIS) {
    for (let attempt = 1; attempt <= 6; attempt++) {
      try {
        const [u, c, s] = await redisPipeline([['HGETALL', HKEY.users], ['HGETALL', HKEY.chats], ['HGETALL', HKEY.sessions]]);
        db = { users: pairsToObject(u), chats: pairsToObject(c), sessions: pairsToObject(s) };
        console.log(`Данные загружены из Upstash: пользователей ${Object.keys(db.users).length}, чатов ${Object.keys(db.chats).length}`);
        return;
      } catch (e) {
        console.error(`Не удалось загрузить данные (попытка ${attempt}/6):`, e.message);
        await sleep(2000);
      }
    }
    // Не стартуем с пустой базой: иначе новые регистрации могли бы занять существующие имена.
    console.error('База недоступна, останавливаюсь. Проверьте UPSTASH_REDIS_REST_URL и UPSTASH_REDIS_REST_TOKEN.');
    process.exit(1);
  }
  if (fs.existsSync(DATA_FILE)) {
    try {
      db = Object.assign({ users: {}, chats: {}, sessions: {} }, JSON.parse(fs.readFileSync(DATA_FILE, 'utf8')));
    } catch (e) {
      console.error('Не удалось прочитать data.json, начинаем с пустой базы:', e.message);
    }
  }
  console.log('Хранилище: файл ' + DATA_FILE + (process.env.RENDER ? ' (на бесплатном Render он стирается при перезапуске!)' : ''));
}

async function flush() {
  if (flushing) return scheduleFlush(300);
  flushing = true;
  try {
    if (!USE_REDIS) {
      for (const k of Object.keys(dirty)) dirty[k].clear();
      const tmp = DATA_FILE + '.tmp';
      await fs.promises.writeFile(tmp, JSON.stringify(db));
      await fs.promises.rename(tmp, DATA_FILE);
      return;
    }
    const taken = { users: [...dirty.users], chats: [...dirty.chats], sessions: [...dirty.sessions] };
    for (const k of Object.keys(taken)) for (const key of taken[k]) dirty[k].delete(key);

    // собираем команды и режем на пачки не больше ~600 КБ (лимит запроса Upstash — 1 МБ)
    const batches = [[]];
    let size = 0;
    for (const kind of Object.keys(taken)) {
      for (const key of taken[kind]) {
        const v = has(db[kind], key) ? db[kind][key] : undefined;
        const cmd = v === undefined ? ['HDEL', HKEY[kind], key] : ['HSET', HKEY[kind], key, JSON.stringify(v)];
        const len = cmd.reduce((n, p) => n + String(p).length, 0);
        if (size + len > 600000 && batches[batches.length - 1].length) {
          batches.push([]);
          size = 0;
        }
        batches[batches.length - 1].push({ kind, key, cmd });
        size += len;
      }
    }
    for (const batch of batches) {
      if (!batch.length) continue;
      try {
        await redisPipeline(batch.map((b) => b.cmd));
      } catch (e) {
        console.error('Не удалось записать в базу, повторю позже:', e.message);
        for (const b of batch) dirty[b.kind].add(b.key);
        scheduleFlush(5000);
      }
    }
  } finally {
    flushing = false;
  }
}

async function flushAll() {
  for (let i = 0; i < 4; i++) {
    clearTimeout(flushTimer);
    flushTimer = null;
    await flush();
    if (!dirty.users.size && !dirty.chats.size && !dirty.sessions.size) return;
  }
}

function migrate() {
  for (const [name, u] of Object.entries(db.users)) {
    let changed = false;
    if (typeof u.coins !== 'number') { u.coins = START_COINS; changed = true; }
    if (typeof u.lastBonus !== 'number') { u.lastBonus = 0; changed = true; }
    if (changed) touch('users', name);
  }
  for (const [token, s] of Object.entries(db.sessions)) {
    if (typeof s === 'string') {
      db.sessions[token] = { user: s, ts: Date.now() };
      touch('sessions', token);
    }
  }
  for (const chat of Object.values(db.chats)) {
    if (!chat.reads) chat.reads = {};
    if (!Array.isArray(chat.messages)) chat.messages = [];
  }
}

const getUser = (name) => (typeof name === 'string' && has(db.users, name) ? db.users[name] : null);
const getChat = (id) => (typeof id === 'string' && has(db.chats, id) ? db.chats[id] : null);

// ===================================================================== файлы ==
// Фото и голосовые лежат отдельно от сообщений: в Upstash (ключ с временем жизни) или в папке media/.
// В сообщении хранится только ссылка (id), сам файл клиент запрашивает, когда он нужен.

const mediaCache = new Map(); // id -> { mime, data }, небольшой кэш в памяти
let mediaCacheBytes = 0;
const MEDIA_CACHE_MAX = 24 * 1024 * 1024;

function cachePut(id, rec) {
  cacheDrop(id);
  mediaCache.set(id, rec);
  mediaCacheBytes += rec.data.length;
  for (const [k, v] of mediaCache) {
    if (mediaCacheBytes <= MEDIA_CACHE_MAX) break;
    mediaCache.delete(k);
    mediaCacheBytes -= v.data.length;
  }
}

function cacheDrop(id) {
  const old = mediaCache.get(id);
  if (old) {
    mediaCache.delete(id);
    mediaCacheBytes -= old.data.length;
  }
}

const MEDIA_CHUNK = 400000;

// Для звонков: бесплатный STUN от Google. Если звонки не соединяются через мобильный интернет,
// добавьте TURN-сервер: переменные TURN_URL, TURN_USER, TURN_PASS (например, от metered.ca).
const ICE_SERVERS = [{ urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302'] }];
if (process.env.TURN_URL) {
  ICE_SERVERS.push({ urls: process.env.TURN_URL.split(',').map((x) => x.trim()), username: process.env.TURN_USER || '', credential: process.env.TURN_PASS || '' });
}

async function saveMedia(id, rec) {
  cachePut(id, rec);
  const raw = rec.mime + ';' + rec.data;
  if (USE_REDIS) {
    // лимит запроса Upstash — 1 МБ, поэтому большие файлы кладём кусками по ~400 КБ
    if (raw.length <= MEDIA_CHUNK) {
      await redisPipeline([['SET', 'msgr:media:' + id, raw, 'EX', MEDIA_TTL]]);
    } else {
      const n = Math.ceil(raw.length / MEDIA_CHUNK);
      for (let i = 0; i < n; i++) {
        await redisPipeline([['SET', `msgr:media:${id}:${i}`, raw.slice(i * MEDIA_CHUNK, (i + 1) * MEDIA_CHUNK), 'EX', MEDIA_TTL]]);
      }
      // главный ключ записываем последним: пока он не появился, файла «нет»
      await redisPipeline([['SET', 'msgr:media:' + id, 'CHUNKS:' + n, 'EX', MEDIA_TTL]]);
    }
  } else {
    await fs.promises.mkdir(MEDIA_DIR, { recursive: true });
    await fs.promises.writeFile(path.join(MEDIA_DIR, id), raw);
  }
}

async function getMedia(id) {
  if (!/^[0-9a-f]{16}$/.test(id)) return null;
  const hit = mediaCache.get(id);
  if (hit) {
    cachePut(id, hit); // освежаем место в кэше
    return hit;
  }
  let raw = null;
  try {
    if (USE_REDIS) {
      raw = (await redisPipeline([['GET', 'msgr:media:' + id]]))[0];
      if (raw && raw.startsWith('CHUNKS:')) {
        const n = parseInt(raw.slice(7), 10);
        const parts = await redisPipeline(Array.from({ length: n }, (_, i) => ['GET', `msgr:media:${id}:${i}`]));
        if (parts.some((p) => p === null || p === undefined)) return null;
        raw = parts.join('');
      }
    } else raw = await fs.promises.readFile(path.join(MEDIA_DIR, id), 'utf8');
  } catch {
    return null;
  }
  if (!raw) return null;
  const i = raw.indexOf(';');
  const rec = { mime: raw.slice(0, i), data: raw.slice(i + 1) };
  cachePut(id, rec);
  return rec;
}

function deleteMedia(id) {
  if (!/^[0-9a-f]{16}$/.test(id)) return;
  cacheDrop(id);
  const done = USE_REDIS ? redisPipeline([['DEL', 'msgr:media:' + id], ...Array.from({ length: 24 }, (_, i) => ['DEL', `msgr:media:${id}:${i}`])]) : fs.promises.unlink(path.join(MEDIA_DIR, id));
  done.catch(() => { /* файла уже нет */ });
}

// короткий текст сообщения для списка чатов, цитат и закрепа
function previewOf(m) {
  if (!m) return '';
  if (m.deleted) return 'Сообщение удалено';
  switch (m.kind) {
    case 'image': return m.text ? '🖼 ' + m.text : '🖼 Фото';
    case 'voice': return '🎤 Голосовое сообщение';
    case 'call': return m.call && m.call.how === 'missed' ? '📞 Пропущенный звонок' : (m.call && m.call.video ? '🎥 Видеозвонок' : '📞 Звонок');
    case 'video': return m.text ? '🎬 ' + m.text : '🎬 Видео';
    case 'sticker': return (m.sticker || '') + ' Стикер';
    case 'gift': return '🎁 Подарок: ' + (m.gift ? m.gift.emoji + ' ' + m.gift.name + (m.gift.count > 1 ? ' ×' + m.gift.count : '') : '');
    case 'poll': return '📊 ' + ((m.poll && m.poll.question) || 'Опрос');
    default: return m.text || '';
  }
}

// ======================================================================= роли ==

const isOwner = (u) => OWNERS.has(u);
const isAdmin = (u) => isOwner(u) || !!(getUser(u) && db.users[u].admin);
const isMod = (u) => isAdmin(u) || !!(getUser(u) && db.users[u].mod);
const roleOf = (u) => (isOwner(u) ? 'owner' : isAdmin(u) ? 'admin' : isMod(u) ? 'moderator' : 'user');
const adminList = () => Object.keys(db.users).filter(isAdmin);
const isVerified = (u) => !!(getUser(u) && db.users[u].verified);
const verifiedList = () => Object.keys(db.users).filter((u) => !db.users[u].banned && db.users[u].verified);
const modList = () => Object.keys(db.users).filter((u) => !isAdmin(u) && isMod(u));

// ============================================================== авторизация ==

function hashPassword(password, salt) {
  return crypto.scryptSync(password, salt, 64).toString('hex');
}

function checkPassword(user, password) {
  const a = Buffer.from(hashPassword(password, user.salt), 'hex');
  const b = Buffer.from(user.hash, 'hex');
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

function newToken(username) {
  const token = crypto.randomBytes(32).toString('hex');
  db.sessions[token] = { user: username, ts: Date.now() };
  touch('sessions', token);
  // не храним больше N сессий на человека
  const mine = Object.entries(db.sessions).filter(([, s]) => s.user === username).sort((a, b) => a[1].ts - b[1].ts);
  while (mine.length > MAX_SESSIONS_PER_USER) {
    const [old] = mine.shift();
    delete db.sessions[old];
    touch('sessions', old);
  }
  return token;
}

function dropSessions(username) {
  for (const [t, s] of Object.entries(db.sessions)) {
    if (s.user === username) {
      delete db.sessions[t];
      touch('sessions', t);
    }
  }
}

// ================================================================== клиенты ==

const clients = new Map(); // username -> Set<ws>

const isOnline = (u) => !!clients.get(u) && clients.get(u).size > 0;

function sendTo(username, payload) {
  const set = clients.get(username);
  if (!set) return;
  const data = JSON.stringify(payload);
  for (const ws of set) if (ws.readyState === 1) ws.send(data);
}

function sendWs(ws, payload) {
  if (ws.readyState === 1) ws.send(JSON.stringify(payload));
}

function broadcastAll(payload) {
  for (const username of clients.keys()) sendTo(username, payload);
}

// =================================================================== статусы ==
const STATUS_TTL = 24 * 3600 * 1000;

// видит ли `viewer` статусы `owner`: если между ними есть личный чат
const statusVisible = (owner, viewer) => !!getChat(dmId(owner, viewer));

function statusFeed(viewer) {
  const now = Date.now();
  const out = [];
  for (const [name, u] of Object.entries(db.users)) {
    if (u.banned || !(u.statuses || []).length) continue;
    if (name !== viewer && !statusVisible(name, viewer)) continue;
    const items = u.statuses.filter((x) => now - x.ts < STATUS_TTL).map((x) => ({
      id: x.id, ts: x.ts, text: x.text, bg: x.bg, media: x.media,
      viewed: name === viewer ? true : x.views.includes(viewer),
      views: name === viewer ? x.views.length : undefined,
    }));
    if (items.length) out.push({ user: name, items });
  }
  return out;
}

function notifyStatus(owner) {
  for (const n of clients.keys()) if (n === owner || statusVisible(owner, n)) sendTo(n, { type: 'status_new', user: owner });
}

// ===================================================================== звонки ==
// Сервер только передаёт сигналы (WebRTC), звук и видео идут напрямую между телефонами.
const calls = new Map();      // id -> { id, from, to, video, state, ts, startedAt, chatId, timer, answerWs }
const userCall = new Map();   // username -> id
const RING_MS = 40000;

function logCall(call, how) {
  const chat = getChat(call.chatId);
  if (!chat) return;
  const dur = call.startedAt ? Math.round((Date.now() - call.startedAt) / 1000) : 0;
  pushMessage(chat, { id: newId(), from: call.from, text: '', ts: Date.now(), kind: 'call', call: { video: !!call.video, how, dur, to: call.to } });
}

function endCall(call, reason, byWho) {
  if (!calls.has(call.id)) return;
  clearTimeout(call.timer);
  calls.delete(call.id);
  if (userCall.get(call.from) === call.id) userCall.delete(call.from);
  if (userCall.get(call.to) === call.id) userCall.delete(call.to);
  for (const u of [call.from, call.to]) sendTo(u, { type: 'call_ended', id: call.id, reason });
  const how = call.startedAt ? 'ended' : reason === 'declined' ? 'declined' : reason === 'cancel' ? 'cancelled' : 'missed';
  logCall(call, how);
}

function kick(username, reason) {
  const set = clients.get(username);
  if (!set) return;
  for (const ws of [...set]) {
    sendWs(ws, { type: 'banned', reason });
    try { ws.close(); } catch { /* ignore */ }
  }
}

function subOf(u) {
  const x = getUser(u);
  return x && x.sub && x.sub.until > Date.now() ? x.sub : null;
}
const rawTierOf = (u) => (subOf(u) || {}).plan || null;
const tierOf = (u) => { const t = rawTierOf(u); return t === 'premiumplus' || t === 'vip1' ? 'premium' : t; };
function subsMap() {
  const o = {};
  for (const [n, u] of Object.entries(db.users)) {
    if (u.sub && u.sub.until > Date.now() && !u.banned) o[n] = { plan: u.sub.plan, until: u.sub.until };
  }
  return o;
}
const bonusFor = (u) => Math.round(DAILY_BONUS * (rawTierOf(u) === 'premiumplus' || rawTierOf(u) === 'vip1' ? 3 : tierOf(u) === 'premium' ? 2 : tierOf(u) === 'plus' ? 1.5 : 1));
const giftPrice = (u, g) => g.limit ? g.price : Math.max(1, Math.round(g.price * (rawTierOf(u) === 'vip1' ? 0.65 : rawTierOf(u) === 'premiumplus' ? 0.8 : tierOf(u) === 'premium' ? 0.9 : 1)));
// Порядковый номер выпуска подарка (как у коллекционных подарков): №1, №2 …
let memMint = {};
function mintBox() {
  const ownerName = [...OWNERS].find((o) => db.users[o]);
  return { ownerName, box: ownerName ? (db.users[ownerName].giftMint = db.users[ownerName].giftMint || {}) : memMint };
}
function takeMint(gid, n) {
  const { ownerName, box } = mintBox();
  box[gid] = (box[gid] || 0) + n;
  if (ownerName) touch('users', ownerName);
  const g = GIFTS.find((x) => x.id === gid);
  if (g && g.limit) broadcastAll({ type: 'gift_stock', id: gid, left: giftLeft(g) });
  return { first: box[gid] - n + 1, total: box[gid] };
}
// лимитированные подарки: сколько ещё можно выпустить (проданный и обменянный назад не возвращается)
const giftLeft = (g) => (g.limit ? Math.max(0, g.limit - (mintBox().box[g.id] || 0)) : Infinity);
// цены лимиток может менять владелец (хранятся у владельца)
// Рынок лимиток: цены сами «дышат» вокруг базовой цены (которую задаёт владелец).
// Коридор узкий (0.88–1.14), чтобы нельзя было заработать на перепродаже (лимитки продаются за 70%).
const MARKET_MS = Number(process.env.MARKET_MS == null ? 600000 : process.env.MARKET_MS);
const MARKET_MIN = 0.88, MARKET_MAX = 1.14;
let memMarket = {};
function marketBox() {
  const { ownerName } = mintBox();
  if (!ownerName) return memMarket;
  const o = db.users[ownerName];
  return (o.giftMarket = o.giftMarket || {});
}
function applyGiftPrices() {
  const { ownerName } = mintBox();
  const gp = (ownerName && db.users[ownerName].giftPrices) || {};
  const mk = marketBox();
  for (const g of GIFTS) if (g.limit) {
    if (g.basePrice == null) g.basePrice = g.price;
    const base = gp[g.id] > 0 ? gp[g.id] : g.basePrice;
    const f = base > 0 && mk[g.id] > 0 ? mk[g.id] : 1;
    g.price = base > 0 ? Math.max(1, f === 1 ? base : Math.round(base * f / 100) * 100) : 0;
  }
}
function marketTick() {
  applyGiftPrices();
  const mk = marketBox();
  const before = {};
  for (const g of GIFTS) if (g.limit && g.price > 0) before[g.id] = g.price;
  for (const id of Object.keys(before)) {
    let f = mk[id] > 0 ? mk[id] : 1;
    f += (1 - f) * 0.06 + (Math.random() - 0.5) * 0.09;
    mk[id] = Math.min(MARKET_MAX, Math.max(MARKET_MIN, Math.round(f * 1000) / 1000));
  }
  applyGiftPrices();
  const prices = {}, dir = {};
  for (const g of GIFTS) if (g.limit && g.price > 0 && g.price !== before[g.id]) { prices[g.id] = g.price; dir[g.id] = g.price > before[g.id] ? 1 : -1; }
  const { ownerName } = mintBox();
  if (ownerName) touch('users', ownerName);
  if (Object.keys(prices).length) broadcastAll({ type: 'gift_prices', prices, dir });
}
if (MARKET_MS > 0) setInterval(marketTick, MARKET_MS).unref();
const giftsCatalog = () => (applyGiftPrices(), GIFTS).map((g) => { const cat = g.limit ? 'limited' : g.cat || EXISTING_CAT[g.id] || 'party'; return g.limit ? { ...g, cat, left: giftLeft(g) } : { ...g, cat }; });

