// ===================================================================== чаты ==

const dmId = (a, b) => 'dm:' + [a, b].sort().join(':');

function getOrCreateDm(a, b) {
  const id = dmId(a, b);
  if (!getChat(id)) {
    db.chats[id] = { id, type: 'dm', name: '', members: [a, b], messages: [], reads: { [a]: 0, [b]: 0 } };
    touch('chats', id);
  }
  return db.chats[id];
}

function ensureAnnounce() {
  if (!getChat(ANNOUNCE_ID)) {
    db.chats[ANNOUNCE_ID] = { id: ANNOUNCE_ID, type: 'channel', name: 'Объявления', members: [], messages: [], reads: {} };
    touch('chats', ANNOUNCE_ID);
  }
  return db.chats[ANNOUNCE_ID];
}

function addToAnnounce(user) {
  const c = ensureAnnounce();
  if (!c.members.includes(user)) {
    c.members.push(user);
    c.reads[user] = c.messages.length; // старые объявления не считаем непрочитанными
    touch('chats', c.id);
  }
}

function chatView(chat, user) {
  const last = chat.messages.length ? chat.messages[chat.messages.length - 1] : null;
  const reads = chat.reads[user] || 0;
  let pinned = null;
  if (chat.pinned) {
    const pm = chat.messages.find((x) => x.id === chat.pinned);
    if (pm && !pm.deleted) pinned = { id: pm.id, from: pm.from, text: previewOf(pm).slice(0, 100) };
  }
  const view = {
    id: chat.id,
    type: chat.type,
    members: chat.members,
    reads: chat.reads,
    total: chat.messages.length,
    unread: Math.max(0, chat.messages.length - reads),
    pinned,
    last: last ? { from: last.from, text: previewOf(last), ts: last.ts, system: !!last.system, deleted: !!last.deleted } : null,
  };
  if (chat.type === 'dm') {
    const peer = chat.members.find((m) => m !== user) || user;
    view.name = peer;
    view.peer = peer;
    view.lastSeen = (getUser(peer) && db.users[peer].lastSeen) || null;
  } else {
    view.name = chat.name;
    view.owner = chat.owner;
  }
  if (chat.type === 'channel' && chat.id !== ANNOUNCE_ID) {
    // чужих подписчиков не раскрываем
    view.members = [...new Set([user, chat.owner])];
    view.reads = { [user]: reads };
    view.subs = chat.members.length;
    view.desc = chat.desc || '';
    view.public = !!chat.public;
    view.verified = !!chat.verified;
    view.mine = chat.owner === user;
    if (chat.owner === user) view.invite = chat.invite;
  }
  return view;
}

function chatsFor(user) {
  return Object.values(db.chats)
    .filter((c) => c.members.includes(user) && (c.type === 'group' || c.type === 'channel' || c.messages.length > 0))
    .map((c) => chatView(c, user));
}

function trimChat(chat) {
  let drop = 0;
  let chars = chat.messages.reduce((n, m) => n + (m.text ? m.text.length : 0), 0);
  while (chat.messages.length - drop > 1 && (chat.messages.length - drop > HISTORY_LIMIT || chars > HISTORY_CHARS)) {
    chars -= chat.messages[drop].text ? chat.messages[drop].text.length : 0;
    drop++;
  }
  if (!drop) return;
  chat.messages.splice(0, drop);
  for (const m of chat.members) chat.reads[m] = Math.max(0, (chat.reads[m] || 0) - drop);
}

// ============================================================ push-уведомления ==
// Работают, даже когда экран выключен или приложение закрыто (Web Push, VAPID, без внешних библиотек).
const PUSH_HOSTS = ['googleapis.com', 'mozilla.com', 'windows.com', 'apple.com'];
let VAPID = null;
const b64u = (b) => Buffer.from(b).toString('base64url');

async function initVapid() {
  try {
    let jwk = null;
    if (USE_REDIS) {
      const [v] = await redisPipeline([['GET', 'msgr:vapid']]);
      if (v) jwk = JSON.parse(v);
    } else if (db.vapid) jwk = db.vapid;
    if (!jwk) {
      const { privateKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'P-256' });
      jwk = privateKey.export({ format: 'jwk' });
      if (USE_REDIS) {
        await redisPipeline([['SETNX', 'msgr:vapid', JSON.stringify(jwk)]]);
        const [v2] = await redisPipeline([['GET', 'msgr:vapid']]);
        jwk = JSON.parse(v2);
      } else { db.vapid = jwk; scheduleFlush(); }
    }
    const priv = crypto.createPrivateKey({ key: jwk, format: 'jwk' });
    VAPID = { priv, pub: b64u(Buffer.concat([Buffer.from([4]), Buffer.from(jwk.x, 'base64url'), Buffer.from(jwk.y, 'base64url')])) };
    console.log('Push-уведомления включены');
  } catch (e) {
    VAPID = null;
    console.error('Push-уведомления отключены:', e.message);
  }
}

function pushEndpointOk(u) {
  try {
    const x = new URL(String(u));
    if (process.env.PUSH_ALLOW_ANY) return true;
    return x.protocol === 'https:' && PUSH_HOSTS.some((h) => x.hostname === h || x.hostname.endsWith('.' + h));
  } catch { return false; }
}

const hkdf = (salt, ikm, info, len) => Buffer.from(crypto.hkdfSync('sha256', ikm, salt, info, len));

// шифрование полезной нагрузки по RFC 8291 (aes128gcm)
function encryptPush(sub, payload) {
  const uaPub = Buffer.from(sub.keys.p256dh, 'base64url');
  const auth = Buffer.from(sub.keys.auth, 'base64url');
  const ecdh = crypto.createECDH('prime256v1');
  ecdh.generateKeys();
  const asPub = ecdh.getPublicKey();
  const shared = ecdh.computeSecret(uaPub);
  const ikm = hkdf(auth, shared, Buffer.concat([Buffer.from('WebPush: info\0'), uaPub, asPub]), 32);
  const salt = crypto.randomBytes(16);
  const cek = hkdf(salt, ikm, Buffer.from('Content-Encoding: aes128gcm\0'), 16);
  const nonce = hkdf(salt, ikm, Buffer.from('Content-Encoding: nonce\0'), 12);
  const plain = Buffer.concat([Buffer.from(JSON.stringify(payload)), Buffer.from([2])]);
  const c = crypto.createCipheriv('aes-128-gcm', cek, nonce);
  const enc = Buffer.concat([c.update(plain), c.final(), c.getAuthTag()]);
  const hdr = Buffer.alloc(21);
  salt.copy(hdr, 0);
  hdr.writeUInt32BE(4096, 16);
  hdr[20] = 65;
  return Buffer.concat([hdr, asPub, enc]);
}

async function sendPush(sub, payload) {
  const origin = new URL(sub.endpoint).origin;
  const head = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  const claims = b64u(JSON.stringify({ aud: origin, exp: Math.floor(Date.now() / 1000) + 12 * 3600, sub: 'mailto:messenger@messenger-nl.onrender.com' }));
  const sig = crypto.sign('sha256', Buffer.from(head + '.' + claims), { key: VAPID.priv, dsaEncoding: 'ieee-p1363' });
  const res = await fetch(sub.endpoint, {
    method: 'POST',
    headers: {
      'Content-Encoding': 'aes128gcm',
      'Content-Type': 'application/octet-stream',
      TTL: '86400',
      Urgency: 'high',
      Authorization: `vapid t=${head}.${claims}.${b64u(sig)}, k=${VAPID.pub}`,
    },
    body: encryptPush(sub, payload),
    signal: AbortSignal.timeout(8000),
  });
  return res.status;
}

const isVisible = (u) => { const set = clients.get(u); if (!set) return false; for (const w of set) if (w.vis === true && w.readyState === 1 && Date.now() - (w.visTs || 0) < 40000) return true; return false; };
const hasPush = (u) => !!(getUser(u) && Array.isArray(db.users[u].push) && db.users[u].push.length);

// отправить уведомление человеку, если он сейчас не смотрит в приложение
function notifyUser(user, payload) {
  if (!VAPID || !hasPush(user) || isVisible(user)) return;
  const u = db.users[user];
  for (const sub of u.push.slice()) {
    sendPush(sub, payload).then((st) => {
      if (st === 404 || st === 410) {
        u.push = u.push.filter((x) => x.endpoint !== sub.endpoint);
        touch('users', user);
      }
    }).catch(() => {});
  }
}

function pushForMessage(chat, message) {
  if (!VAPID || message.system || message.deleted || !message.from) return;
  const body = previewOf(message).slice(0, 140);
  for (const member of chat.members) {
    if (member === message.from) continue;
    notifyUser(member, {
      title: chat.type === 'dm' ? (nicksMap()[message.from] || message.from) : (chat.name || 'Чат'),
      body: chat.type === 'dm' ? body : (nicksMap()[message.from] || message.from) + ': ' + body,
      chatId: chat.id,
      tag: chat.id,
      ts: message.ts || Date.now(),
    });
  }
}

